import { defineConfig } from 'vite';
import tailwindcss from '@tailwindcss/vite'
import { nodePolyfills } from 'vite-plugin-node-polyfills';
import svgr from 'vite-plugin-svgr';
import { resolve } from 'path';
import { existsSync, readFileSync } from 'fs';

/**
 * The SEO landing pages are generated by `node scripts/generate-seo-pages.mjs`, which writes
 * `seo/pages.manifest.json` listing every HTML entry (homepage, app shell, one page per tool).
 * Registering them here turns each one into a real static route in dist/.
 */
function seoEntries(): Record<string, string> {
  const manifest = resolve(__dirname, 'seo/pages.manifest.json');
  if (!existsSync(manifest)) {
    console.warn('[vite] seo/pages.manifest.json missing — run `node scripts/generate-seo-pages.mjs` first');
    return {};
  }
  const { inputs } = JSON.parse(readFileSync(manifest, 'utf8'));
  return Object.fromEntries(
    Object.entries<string>(inputs).map(([name, file]) => [name, resolve(__dirname, file)])
  );
}

export default defineConfig({
  plugins: [
    tailwindcss(),
    // Stirling's icon registry imports its svgs as `?react` (SVGR) components.
    svgr({ include: ['**/*.svg?react', '**/icons/**/*.svg'] }),
    nodePolyfills({
      include: ['buffer', 'stream', 'util', 'zlib', 'process'],
      globals: {
        Buffer: true,
        global: true,
        process: true,
      },
    }),
  ],
  resolve: {
    alias: {
      stream: 'stream-browserify',
      zlib: 'browserify-zlib',
      /**
       * The vendored Stirling editor keeps its own `@editor/*` imports untouched (see
       * scripts/vendor-stirling.mjs), so the alias points at the vendored tree.
       */
      '@editor': resolve(__dirname, 'src/stirling'),
      /**
       * ES-module wrapper around JSZip. scripts/vendor-stirling.mjs rewrites the donor's
       * `import("jszip")` calls to this specifier so Rollup stops emitting a CJS augmented namespace
       * into the jszip/commonjs-helper chunks that every other tool page loads.
       */
      'jszip-lazy': resolve(__dirname, 'src/js/editor/stirling/jszip-loader.ts'),
      /**
       * clsx ships ESM and CJS and reaches the editor through react-rnd -> react-draggable, whose CJS
       * build `require()`s it. Vite answers a require() of an ESM module by synthesising an augmented
       * namespace, and that helper lands in the shared `_commonjsHelpers` chunk that every tool page
       * loads (+0.2 KB gzip each — see scripts/size-report.mjs). Pointing at the CJS build keeps the
       * shared chunk at its pre-vendoring size; the ESM entry stays in use for Mantine.
       */
      clsx: resolve(__dirname, 'node_modules/clsx/dist/clsx.js'),
    },
  },
  optimizeDeps: {
    include: ['pdfkit', 'blob-stream'],
  },
  build: {
    rollupOptions: {
      input: {
        /**
         * The GA4 loader (src/js/analytics.ts) is built as its own entry because the deferred bootstrap
         * in the generated HTML fetches it by URL at runtime. It is referenced by no `<script src>` tag
         * and by no page module, so it is NOT part of any page's first-load graph and no page's
         * measured size changes (scripts/size-report.mjs walks only the eager chunk graph).
         */
        analytics: resolve(__dirname, 'src/js/analytics.ts'),
        about: resolve(__dirname, 'about.html'),
        contact: resolve(__dirname, 'contact.html'),
        faq: resolve(__dirname, 'faq.html'),
        privacy: resolve(__dirname, 'privacy.html'),
        terms: resolve(__dirname, 'terms.html'),
        // homepage (main) and the tool landing pages from the SEO manifest
        ...seoEntries(),
      },
      output: {
        /**
         * No manualChunks on purpose. The per-tool dynamic imports in src/js/logic/lazy.ts already make
         * Rollup emit one chunk per tool plus shared chunks for libraries several tools use (pdf-lib,
         * pdf.js), while single-tool dependencies (heic2any, Tesseract, cropperjs) stay inside that
         * tool's chunk. Hand-written chunk groups broke that: side-effect imports then dragged e.g.
         * heic2any into the merge chunk.
         *
         * The GA4 loader is the one exception to the content hash: the deferred bootstrap in the
         * generated HTML is a classic inline script, so Vite never sees its `import(…)` and cannot
         * hash that URL for it. A stable file name keeps the two in sync; every other entry and chunk
         * keeps `[name]-[hash]`.
         */
        entryFileNames: (chunk) => (chunk.name === 'analytics' ? 'assets/analytics-v2.js' : 'assets/[name]-[hash].js'),
        chunkFileNames: 'assets/[name]-[hash].js',
      },
    },
  },
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: './src/tests/setup.ts',
    coverage: {
      provider: 'v8',
      reporter: ['text', 'json', 'html'],
      exclude: [
        'node_modules/',
        'src/tests/',
        '*.config.ts',
        '**/*.d.ts',
        'dist/',
      ],
    },
  },
});